(function(){const t=14,n=240,a=160;let r=0,o=0;const e=new Float32Array(t),s=new Float32Array(t),l=new Float32Array(t),i=new Float32Array(t);return{init:function(n){r=n,o=0;for(let n=0;n<t;n++)e[n]=Math.randInt(628)/100,s[n]=(Math.randInt(30)+15)/1e3*(n%2?1:-1)},draw:function(h){"ram";const c=r+3;if(h.setColor(3),o>0){h.setColor(0);for(let n=0;n<t;n++)h.drawLine(0|l[n],0|i[n],0|l[(n+c)%t],0|i[(n+c)%t]);h.setColor(3)}const f=100+130*Math.abs(Math.sin(o/41)),M=70+90*Math.abs(Math.sin(o/53+1));for(let o=0;o<t;o++)e[o]+=s[o]*(1+.5*r),l[o]=n+f*Math.cos(e[o]*(1+o%3*.25)),i[o]=a+M*Math.sin(e[o]*(1+o%4*.18));for(let n=0;n<t;n++)h.drawLine(0|l[n],0|i[n],0|l[(n+c)%t],0|i[(n+c)%t]);o++}}});